mapper.update:
update agent_key_file.report_runtime_lock
   set lease_owner = #{owner}, lease_until = #{leaseUntil}, update_time = #{now}
 where lock_name = #{lockName}
   and (lease_owner is null or lease_until is null
        or lease_until < #{now} or lease_owner = #{owner})

update agent_key_file.report_runtime_lock
   set lease_owner = null, lease_until = null, update_time = current_timestamp
 where lock_name = #{lockName} and lease_owner = #{owner}
